// ---- TabBar component ----
async function buildTabBar(current){
  const c = figma.createComponent();
  c.name = 'TabBar/'+current;
  c.resize(402, 78);
  c.fills = solid(COLORS.bg);
  c.strokes = solid(COLORS.border); c.strokeWeight=1; c.strokeAlign='INSIDE';
  const tabs = [
    {key:'Home', icon:MEDIA.Icon_Tab_Home, label:'Home'},
    {key:'Wallet', icon:MEDIA.Icon_Tab_Wallet, label:'Wallet'},
    {key:'Guide', icon:MEDIA.Icon_Tab_Guide, label:'Guide'},
    {key:'Chart', icon:MEDIA.Icon_Tab_Chart, label:'Chart'},
  ];
  const slotW = 402/4;
  for (let i=0;i<tabs.length;i++){
    const t = tabs[i];
    const active = t.key === current;
    const icon = await getInst(t.icon);
    icon.resize(24,24);
    icon.x = slotW*i + slotW/2 - 12; icon.y = 14;
    if (!active) icon.opacity = 0.45;
    c.appendChild(icon);
    const lbl = mkText('label', t.label, 11, active?'SemiBold':'Regular', active?COLORS.brand:COLORS.textSec);
    lbl.resize(slotW-8, 14); lbl.textAlignHorizontal='CENTER';
    lbl.x = slotW*i+4; lbl.y = 42;
    c.appendChild(lbl);
    if (active){
      const dot = figma.createEllipse();
      dot.resize(5,5); dot.x = slotW*i+slotW/2-2.5; dot.y = 62;
      dot.fills = solid(COLORS.brand);
      c.appendChild(dot);
    }
  }
  stage.appendChild(c);
  return c;
}
