  f.appendChild(bar);
  const tabs=[{n:'Home',icon:'1:248'},{n:'Wallet',icon:'1:249'},{n:'Guide',icon:'1:247'},{n:'Chart',icon:'1:246'}];
  for(let i=0;i<4;i++){
    const icon = await getInst(tabs[i].icon); icon.resize(26,26);
    icon.x = 40 + i*90; icon.y = f.height-55;
    if(tabs[i].n===current){ icon.fills=solid(COLORS.brand); } 
    icon.name='Tab_'+tabs[i].n;
    f.appendChild(icon);
  }
  return bar;
}

