const COLORS = {
  brand:{r:0x03/255,g:0x73/255,b:0xF3/255}, bg:{r:1,g:1,b:1},
  surface:{r:0.96,g:0.97,b:0.98}, text:{r:0.04,g:0.07,b:0.13},
  textSec:{r:0.42,g:0.46,b:0.52}, white:{r:1,g:1,b:1},
};
function solid(c,o){return [{type:'SOLID', color:c, opacity:o===undefined?1:o}];}
function mkText(name,content,size,weight,color,font){
  const t=figma.createText(); t.name=name; t.fontName={family:font||'Poppins',style:weight};
  t.fontSize=size; t.characters=content; t.fills=solid(color); return t;
}
async function getInst(id){ const n=await figma.getNodeByIdAsync(id); return n.createInstance(); }
function circleBtn(x,y,d,fill){ const e=figma.createEllipse(); e.resize(d,d); e.x=x; e.y=y; e.fills=solid(fill||{r:1,g:1,b:1},0.95); return e; }
function rr(x,y,w,h,radius,fill){ const r=figma.createRectangle(); r.resize(w,h); r.x=x; r.y=y; r.cornerRadius=radius; r.fills=solid(fill); return r; }

async function buildTabBar(parent, current){
  const tabY=800;
  const bar = rr(0,tabY,402,74,0,COLORS.white); parent.appendChild(bar);
  const tabs=[['Home','1:248'],['Wallet','1:249'],['Guide','1:247'],['Chart','1:246']];
  const w=402/4;
  let tx=0;
  for(const [label,iconId] of tabs){
    const sel = label===current;
    const icon = await getInst(iconId); icon.resize(24,24); icon.x=tx+w/2-12; icon.y=tabY+12; 
    if(sel){ icon.fills=solid(COLORS.brand); } 
    parent.appendChild(icon);
    const lab = mkText('tabLabel',label,10,sel?'SemiBold':'Regular', sel?COLORS.brand:COLORS.textSec); lab.resize(w,14); lab.textAlignHorizontal='CENTER'; lab.x=tx; lab.y=tabY+40; parent.appendChild(lab);
    tx+=w;
  }
}

