for(const [frameId, nodeId, targetId, trigger] of links){
  const frame = await figma.getNodeByIdAsync(frameId);
  const node = await figma.getNodeByIdAsync(nodeId);
  const target = await figma.getNodeByIdAsync(targetId);
  if(!node || !target){ continue; }
  const reaction = {
    trigger: trigger==='AFTER_TIMEOUT' ? {type:'AFTER_TIMEOUT', timeout:1200} : {type:'ON_CLICK'},
    actions: [{type:'NODE', destinationId: target.id, navigation:'NAVIGATE', transition: null, preserveScrollPosition:false}]
  };
  try{
    node.reactions = [reaction];
    count++;
  }catch(e){}
}
